/**
 * Inline SVG for a tool.
 *
 * @param array $tool Tool.
 * @return string
 */
function raze_tool_svg( $tool ) {
	$color = isset( $tool['color'] ) ? $tool['color'] : 'currentColor';
	if ( 'HighLevel' === $tool['name'] ) {
		return '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'
			. '<path d="M5 20V9M2.5 11.5 5 9l2.5 2.5" stroke="#FFBC00"/>'
			. '<path d="M12 20V4M9.5 6.5 12 4l2.5 2.5" stroke="#188BF6"/>'
			. '<path d="M19 20v-8M16.5 14.5 19 12l2.5 2.5" stroke="#37CA37"/></svg>';
	}
	return '<svg viewBox="0 0 24 24" width="24" height="24" fill="' . esc_attr( $color ) . '" aria-hidden="true" focusable="false"><path d="' . esc_attr( $tool['path'] ) . '"/></svg>';
}
